// network id = salted SHA-256 of the IP (the raw IP is never stored)
async function netId(req, env) {
  const ip = req.headers.get("cf-connecting-ip") || req.headers.get("x-forwarded-for") || "0.0.0.0";
  const d = await crypto.subtle.digest("SHA-256", new TextEncoder().encode("net:" + ip + ":" + (env.ADMIN_KEY || "")));
  return [...new Uint8Array(d)].slice(0, 8).map((b) => b.toString(16).padStart(2, "0")).join("");
}
