  if (typeof fp !== "string" || !/^[0-9a-f]{16,64}$/.test(fp)) return null;
  const os = device(ua).split(" · ")[0];
  const d = await crypto.subtle.digest("SHA-256", new TextEncoder().encode("dev:" + fp + "|" + os + ":" + (env.ADMIN_KEY || "")));
  return [...new Uint8Array(d)].slice(0, 8).map((b) => b.toString(16).padStart(2, "0")).join("");
