  if (lock && lock.until > now) return { error: `محاولات خاطئة كثيرة. حاول بعد ${Math.ceil((lock.until - now) / 60000)} دقيقة`, status: 429 };
  const st = code.length === 6 ? await db.prepare("SELECT id, name, role FROM staff WHERE code = ?").bind(code).first() : null;
  if (st) return { staff: st };
  const n = (lock && lock.until === 0 ? lock.n : 0) + 1, until = n >= 30 ? now + 15 * 60000 : 0;
  await db.prepare("INSERT INTO authfail (iph, n, until) VALUES (?, ?, ?) ON CONFLICT(iph) DO UPDATE SET n = excluded.n, until = excluded.until")
